import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { createReturnFulfillmentWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await createReturnFulfillmentWorkflow(req.scope)
    .run({
      input: {
        location_id: "sloc_123",
        provider_id: "provider_123",
        delivery_address: {
          first_name: "John",
          last_name: "Doe",
          address_1: "Test street 1",
          city: "Stockholm",
          country_code: "se",
          postal_code: "12345",
          phone: "123456789"
        },
        items: [{
          quantity: 1,
          sku: "shirt",
          title: "Shirt",
          barcode: "123"
        }],
        order: {
          id: "order_123"
          // other order details...
        }
      }
    })

  res.send(result)
}

